const e={stage:{title:"Dodaios Verse",loading:"Loading deck",unavailable:"The ship needs WebGL, which this window cannot start right now.",deck_missing:"This deck has not been built yet.",help:"Third person: WASD or the arrow keys walk the commander, Shift hurries, E works the station within reach. 1, 2 and 3 pick the bird's-eye view, third or first person; V cycles them. Drag to look around, scroll to zoom. Click the deck to walk there, click a crew member for their record. Hold F to unleash Arc Storm, lightning from both hands. B folds out the hoverboard, which glides across the deck much faster.",help_eye:"Third and first person play like a shooter: a click on the view takes the mouse, moving it turns the camera, Esc gives it back. WASD walks relative to the view, Shift hurries; the left button or E works what the crosshair is on (a crew member, a station), else E works the station within reach. Scroll to move the camera in or out: all the way in is first person, scrolling out of it comes back. 1, 2 and 3 pick the bird's-eye view, third or first person; V cycles them. The settings button on the tool rail sets mouse sensitivity, inverted look, field of view and quality. Hold F to unleash Arc Storm, lightning from both hands. B folds out the hoverboard, which glides across the deck much faster."},deck:{label:"Deck {n}",bridge:"Command Bridge",bridge_about:"Officers at their consoles, the briefing room",ops:"Operations Deck",ops_about:"Mess hall, crew quarters, records hall, simulators",engineering:"Reactor Engineering",engineering_about:"Technicians at the terminals: your coding agents",hangar:"Main Hangar",hangar_about:"New crew arrive here by shuttle"},state:{working:"On duty",waiting:"Needs you",idle:"Off duty",paused:"Stood down",error:"Fault"},crew:{aboard:"{count} aboard",working:"{count} on duty",waiting:"{count} need you"},station:{agents_list:{name:"Command station",action:"Open the crew list"},team:{name:"Briefing table",action:"Open the team"},service_record:{name:"Records hall",action:"Open your service record"},mess_call:{name:"Mess hall",action:"Call the off-duty crew to the mess"},games:{name:"Simulator room",action:"Start a simulation"},quartermaster:{name:"Quartermaster",action:"Choose your uniform"},coding_launcher:{name:"Master systems console",action:"Start coding agents"},create_agent:{name:"Arrivals desk",action:"Bring a new officer aboard"},lift:{name:"Turbolift",action:"Ride to another deck"}},card:{status:"Status",rank:"Rank",post:"Post",open:"Open chat",open_pane:"Open terminal",show:"Show",walk:"Walk there",close:"Close"},post:{console:"Bridge console",terminal:"Engineering terminal",briefing:"Briefing room",mess:"Mess hall",corridor:"Main corridor",viewport:"Forward viewports",bunk:"Crew quarters",workshop:"Engineering",elsewhere:"Elsewhere aboard"},tools:{view:"View",follow:"Third person",overview:"Bird's-eye",lift:"Turbolift",commander:"Commander",settings:"View settings",help:"Help",duel:"Duel",first:"First person",first_unavailable:"First person needs this deck's eye-level scene on the full-size stage.",click_to_look:"Click to look around",first_too_small:"Make this panel at least {width} × {height} for third and first person.",click_for_keys:"Click here so the keys reach the ship",board:"Hoverboard"},settings:{title:"View settings",sensitivity:"Mouse sensitivity",invert_y:"Invert vertical look",quality:"Render quality",quality_auto:"Auto",quality_high:"High",quality_low:"Low",quality_note:"Auto starts high and lowers the quality on a graphics card that cannot keep about 45 frames per second.",quality_now:"Now rendering: {tier}.",mouse_lock:"In third and first person a click on the view takes the mouse: moving it turns the camera, the left button works what the crosshair is on. Esc gives it back; L takes or releases it too.",reset:"Reset",fov_third:"Field of view, third person",fov_first:"Field of view, first person"},lift:{title:"Turbolift",switch:"Change deck",here:"This deck"},notice:{mess_called:"{count} off-duty crew called to the mess.",mess_nobody:"Nobody is off duty right now.",mess_ended:"The crew goes back to their routine.",no_team:"No team meets at this table yet. Create one in the crew list.",view_overview:"Bird's-eye view: WASD pans the map. 2 or 3 takes you back to the commander.",view_follow:"Third person: WASD walks the commander, E works the station within reach. V cycles the views.",view_follow_eye:"Third person: the mouse aims the view, WASD walks, the wheel zooms (all the way in is first person). Esc frees the mouse.",mouse_look:"Mouse look: move the mouse to turn the camera, click to work what the crosshair is on. Esc releases the mouse.",view_first:"First person: the mouse aims the view, WASD walks, scrolling out returns to third person. Esc frees the mouse."},screen:{standby:"STANDBY",vacant:"VACANT",fault:"FAULT",waiting:"AWAITING ORDERS"},launcher:{title:"Master systems console",workspace:"Workspace",cli:"Agent",count:"How many",task:"First task (optional)",start:"Start",starting:"Starting {count}…",started:"{count} started.",failed:"Could not start: {reason}",none:"No coding agent is installed.",no_workspace:"Open a workspace in the IDE first.",open_ide:"Open the IDE"},games:{title:"Simulator room",loading:"Loading the simulation…"},duel:{tool:"Duel",terminal:"Duel terminal",start:"Start a duel",title:"Reactor duel",intro:"A one-on-one blaster duel in the Reactor Shaft against a combat bot. Best of three rounds; leave at any time.",ride:"The turbolift takes you down to Reactor Engineering first.",choose:"Choose the opponent",difficulty:{normal:"Normal",normal_about:"Learn the blaster, the shield and the vent.",hard:"Hard",hard_about:"A fair fight for a good player.",elite:"Elite",elite_about:"Fast and precise: parries, punishes, reads your strafing."},controls:{title:"Controls",move:"Move",sprint:"Sprint",fire:"Fire",ads:"Aim down the sights",shield:"Energy shield (hold)",dodge:"Dodge roll",vent:"Vent heat; again inside the window vents at once",pause:"Pause; again to leave",lmb:"Left mouse",rmb:"Right mouse",space:"Space",shift:"Shift",esc:"Esc"},hud:{you:"You",bot:"Bot",round:"Round {n}",health:"Health",shield:"Shield",heat:"Heat",roll:"Roll",ready:"Ready",overheated:"Overheated",venting:"Venting",vent_hint:"R in the gold window",shield_down:"Down {s} s",parry_ready:"Parry ready",parry_locked:"Parry cooling",surge:"Reactor surge: positions revealed",fight:"Fight",click_to_aim:"Click to aim",vent:"Vent"},callout:{parry:"Parry",parried:"Parried",perfect_vent:"Perfect vent",vent_miss:"Vent missed",overheat:"Overheated",shield_break:"Shield broken",deflect:"Deflected"},round:{won:"Round won",lost:"Round lost",draw:"Round drawn",kill:"Knockout",time:"Time: more health wins",trade:"Both down"},pause:{title:"Paused",resume:"Resume",leave:"Leave the duel",hint:"The match waits. Esc again leaves it."},result:{won:"Victory",lost:"Defeat",draw:"Draw",cancelled:"Duel ended",rounds:"Rounds {me} : {them}",against:"Against the {tier} bot",accuracy:"Accuracy",damage:"Damage dealt",headshots:"Headshots",parries:"Parries",blocks:"Blocks",perfect_vents:"Perfect vents",rematch:"Rematch",leave:"Back to the ship"},notice:{needs_eye:"Duels need the third-person 3D view.",left:"You left the duel."}},board:{on:"Hoverboard out: WASD glides, Shift boosts. B folds it away.",off:"Hoverboard folded away."},takeover:{title:"Terminal",action:"Take over the terminal",keys:"Keyboard to the agent",hint_live:"Your keys go straight to the agent: type, Enter sends, Esc interrupts it, Ctrl+V pastes. Ctrl+Q leaves the terminal.",placeholder:"Prompt for this agent",send:"Send"}},t={verse:e};export{t as default,e as verse};
